function oneEditApart(s: string, t: string): boolean {
  if (s.length > t.length) [s, t] = [t, s];
  const m = s.length, n = t.length;
  if (n - m > 1) return false;
  let i = 0;
  while (i < m && s[i] === t[i]) i++;
  if (i === m) return n === m + 1; // only an extra char at the end
  const shift = n === m ? 1 : 0;   // replace skips both, insert skips only t
  for (let a = i + shift, b = i + 1; a < m; a++, b++) if (s[a] !== t[b]) return false;
  return true;
}

